<script setup lang="ts">
import {onMounted,ref} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {useWorkforce} from '../context'
import {useWorkforceText} from '../text'
import {employeeDraft} from '../employeeDraft'
import {usePositionText} from '../positionText'
import {WorkforceApiError} from '../api'
import type {Employee,EmployeeWrite,Position} from '../types'
import {useDocumentText} from '../documentText'
import EmployeeDocuments from '../components/EmployeeDocuments.vue'
import EmployeeAccountFields from '../components/EmployeeAccountFields.vue'
import EmployeeLoginSettings from '../components/EmployeeLoginSettings.vue'
const {api,home,store,current}=useWorkforce(),route=useRoute(),router=useRouter(),{t,error}=useWorkforceText()
const existing=String(route.params.employeeId||''),id=existing||crypto.randomUUID(),draft=ref<EmployeeWrite|null>(null),busy=ref(false),failure=ref(''),loading=ref(true),editable=ref(true),linked=ref(false)
const {d}=useDocumentText(),{j}=usePositionText(),positions=ref<Position[]>([]),originalPosition=ref<string|null>(null)
onMounted(async()=>{try{const e=existing?await api().get<Employee>(`/employees/${id}`):undefined;if(!current())return;editable.value=e?.editable??true;linked.value=!!e?.accountId;if(editable.value&&home.value?.employeeManage){const options=await api().get<Position[]>('/positions');if(!current())return;positions.value=options;originalPosition.value=e?.positionId??null;draft.value=employeeDraft(home.value,store.value,e);draft.value.positionId=e?.positionId??null}}catch(e){if(current())failure.value=error(e)}finally{if(current())loading.value=false}})
async function save(){if(!draft.value||busy.value)return;busy.value=true;failure.value='';try{const c={...draft.value,birthDate:draft.value.birthDate||null,companyEffectiveDate:existing?draft.value.companyEffectiveDate:draft.value.hireDate};await api().put(`/employees/${id}`,c);if(current())await router.push(`/stores/${store.value}/workforce/employees`)}catch(e){if(current())failure.value=e instanceof WorkforceApiError&&e.code==='WORKFORCE_POSITION_UNAVAILABLE'?j('unavailable'):e instanceof WorkforceApiError&&e.code==='WORKFORCE_HIRE_DATE_IN_USE'?d('hireInUse'):error(e)}finally{if(current())busy.value=false}}
</script>
<template><section class="wf-panel wf-form-panel"><h2>{{t(existing?'edit':'create')}}</h2><p v-if="failure" role="alert" class="wf-error">{{failure}}</p><p v-if="loading" role="status">{{t('loading')}}</p><p v-else-if="!editable||!home?.employeeManage" role="alert">{{t('noAccess')}}</p><form v-else-if="draft" @submit.prevent="save"><fieldset :disabled="busy"><div class="wf-grid"><label>{{t('employeeNo')}}<input v-model="draft.employeeNo" required maxlength="40"></label><label>{{t('name')}}<input v-model="draft.name" required maxlength="100"></label><label>{{d('englishName')}}<input v-model="draft.englishName" maxlength="100"></label><label>{{d('birthDate')}}<input v-model="draft.birthDate" type="date" :max="draft.hireDate||undefined"></label><label>{{t('phone')}}<input v-model="draft.phone" maxlength="40" type="tel"></label><label>{{t('email')}}<input v-model="draft.email" maxlength="160" type="email"></label><label>{{t('jobTitle')}}<select v-model="draft.positionId" @change="draft.jobTitle=''" :aria-label="t('jobTitle')"><option :value="null">{{j('choose')}}</option><option v-for="p in positions.filter(p=>p.enabled||p.id===originalPosition)" :key="p.id" :value="p.id">{{p.name}}{{p.enabled?'':' · '+j('retained')}}</option></select><RouterLink v-if="home?.headOffice" :to="`/stores/${store}/workforce/positions`">{{j('manage')}}</RouterLink><small v-else>{{j('contact')}}</small></label><label>{{t('hireDate')}}<input v-model="draft.hireDate" required type="date" :disabled="!!existing&&!home?.headOffice"></label><label>{{d('availability')}}<select v-model="draft.enabled"><option :value="true">{{d('enabled')}}</option><option :value="false">{{d('disabled')}}</option></select><small>{{d('employmentHint')}}</small></label><label>{{t('status')}}<select v-model="draft.status"><option value="active">{{t('active')}}</option><option value="left">{{t('left')}}</option></select></label><label v-if="draft.status==='left'">{{t('leaveDate')}}<input v-model="draft.leaveDate" required type="date" :min="draft.hireDate||undefined"></label></div><template v-if="!existing"><div class="wf-grid"><label>{{t('company')}}<select v-model="draft.companyId" required><option :value="null" disabled>{{t('select')}}</option><option v-for="c in home?.companies" :key="c.id" :value="c.id">{{c.name}}</option></select></label><label>{{t('mainStore')}}<select v-model="draft.mainStoreId" required @change="draft.storeIds=[store,draft.mainStoreId!].filter((v,i,a)=>a.indexOf(v)===i)"><option v-for="s in home?.stores" :key="s.id" :value="s.id">{{s.name}}</option></select></label></div><p class="wf-hint">{{t('newEmployeeHint')}}</p></template><EmployeeAccountFields v-if="!linked" :draft="draft" :accounts="home?.accounts||[]"/><p v-else class="wf-hint">{{t('accountHint')}}</p></fieldset><footer class="wf-form-actions"><RouterLink class="wf-button" :to="`/stores/${store}/workforce/employees`">{{t('cancel')}}</RouterLink><button class="primary" :disabled="busy">{{t(busy?'saving':'save')}}</button></footer></form></section><EmployeeLoginSettings v-if="existing&&linked&&editable&&home?.employeeManage&&!loading" :employee-id="id"/><EmployeeDocuments v-if="existing&&editable&&home?.employeeManage&&!loading" :employee-id="id"/></template>
